local a=require("fcs.comms.protocol")local b={}b.CMD_KIND="eh2_beacon_update"b.ACK_KIND="eh2_beacon_update_ack"function b.validToken(c)return type(c)=="string"and c:gsub("%s","")~=""end;function b.command(d)return{k=b.CMD_KIND,token=d}end;function b.ack(e)return{k=b.ACK_KIND,id=e}end;function b.encode(f)return a.encode(f)end;function b.decode(g)local h=a.decode(g)if type(h)~="table"then return nil end;if h.k==b.CMD_KIND or h.k==b.ACK_KIND then return h end;return nil end;function b.accepts(f,i)if type(f)~="table"or f.k~=b.CMD_KIND then return false end;if not b.validToken(i)then return false end;if not b.validToken(f.token)then return false end;return f.token==i end;return b